CREATE TABLE public.advisory_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), full_name text NOT NULL CHECK (char_length(full_name) BETWEEN 2 AND 100), phone text NOT NULL CHECK (char_length(phone) BETWEEN 9 AND 16), email text NOT NULL CHECK (char_length(email) <= 255), preferred_time text NOT NULL CHECK (preferred_time IN ('09:00–12:00','12:00–15:00','15:00–18:00')), selected_plan text CHECK (char_length(selected_plan) <= 100), consent boolean NOT NULL CHECK (consent = true)); GRANT ALL ON public.advisory_requests TO service_role; ALTER TABLE public.advisory_requests ENABLE ROW LEVEL SECURITY;